const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');

  const q = $input.first().json.query || {};
  const allowedStatus = ['draft','approved','signed'];
  const status = (q.status && allowedStatus.includes(q.status)) ? q.status : null;
  const projectId = q.project_id || null;
  const limit = Math.min(parseInt(q.limit || '200'), 500);

  return [{ json: {
    user_id:   payload.sub,
    tenant_id: payload.tenant_id || null,
    role:      payload.role      || 'architect',
    request_id: 'req_' + Math.random().toString(36).slice(2, 10),
    filters: { status, project_id: projectId, limit }
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const items = $input.all().map(i => i.json).filter(j => j && j.id);
const sess  = $('Decode JWT + Params').first().json;

return [{ json: {
  data: items.map(a => ({
    id:                       a.id,
    tenant_id:                a.tenant_id,
    project_id:               a.project_id,
    project_name:             a.project_name,
    visit_date:               a.visit_date,
    audio_url:                a.audio_url,
    audio_duration_seconds:   a.audio_duration_seconds,
    transcript_raw:           a.transcript_raw,
    transcript_categorized:   a.transcript_categorized,
    observations:             a.observations,
    photos:                   a.photos,
    acuerdos:                 a.acuerdos,
    proxima_visita_prevista:  a.proxima_visita_prevista,
    pdf_url:                  a.pdf_url,
    status:                   a.status,
    approved_at:              a.approved_at,
    signed_at:                a.signed_at,
    created_at:               a.created_at
  })),
  meta: {
    request_id: sess.request_id,
    timestamp:  new Date().toISOString(),
    count:      items.length,
    filters:    sess.filters
  }
}}];
